using System.Windows;using OncaPDV.Domain;using OncaPDV.Infrastructure;namespace OncaPDV.Desktop;public partial class CustomerHistoryWindow:Window{private readonly CustomerProfile _customer;private readonly OperationalService _ops=new(AppServices.Database,AppServices.Paths);public CustomerHistoryWindow(CustomerProfile c){_customer=c;InitializeComponent();TitleText.Text=$"Histórico — {c.Name}";Loaded+=async(_,_)=>Sales.ItemsSource=await _ops.CustomerSalesAsync(c.Id);}private async Task Pdf(bool second){if(Sales.SelectedItem is not Sale s)return;var file=await _ops.SalePdfAsync(s,second);MessageBox.Show($"PDF gerado:\n{file}");}private async void Pdf_Click(object s,RoutedEventArgs e)=>await Pdf(false);private async void Second_Click(object s,RoutedEventArgs e)=>await Pdf(true);}
